// A resposta do HTTP está em $json.data como STRING JSON.
// Parseia e tenta achar o lead_id em diferentes formatos.

function toObj(x) {
  if (!x) return null;
  if (typeof x === 'string') {
    try { return JSON.parse(x); } catch(e) { return null; }
  }
  return x;
}

const raw = $json.body ?? $json.data ?? $json;
const src = toObj(raw) ?? {};  // agora src é objeto (ou {})

// Procura o id em formatos comuns do Kommo
function pickLeadId(obj){
  if (!obj || typeof obj !== 'object') return null;

  // { _embedded: { leads: [ { id } ] } }
  if (obj._embedded?.leads?.[0]?.id) return obj._embedded.leads[0].id;

  // [ { id } ]
  if (Array.isArray(obj) && obj[0]?.id) return obj[0].id;

  // { id: 123 }
  if (Number.isInteger(obj.id)) return obj.id;

  // [ { _embedded: { leads: [ { id } ] } } ]
  if (Array.isArray(obj) && obj[0]?._embedded?.leads?.[0]?.id)
    return obj[0]._embedded.leads[0].id;

  return null;
}

const lead_id = pickLeadId(src);

// Deixo __kommoResp para debug visual
return [{ json: { lead_id, __kommoResp: src } }];

// Suporta payloads com ou sem "body"
const src = ($json && $json.body && typeof $json.body === 'object') ? $json.body : $json;

function toInt(v){
  const n = Number(v);
  return Number.isFinite(n) && n > 0 ? n : null;
}

function pick(...keys){
  for (const k of keys){
    if (src[k] !== undefined && src[k] !== null && src[k] !== '') return src[k];
    if ($json[k] !== undefined && $json[k] !== null && $json[k] !== '') return $json[k];
  }
  return null;
}

// IDs vindos da mensagem (lead REAL da conversa)
const msgLead = toInt(pick("message[add][0][element_id]", "message[add][0][entity_id]"));
const msgContact = toInt(pick("message[add][0][contact_id]"));

// Timestamp epoch -> ISO
const createdAt = toInt(pick("message[add][0][created_at]")) || 0;
const message_ts_iso = createdAt ? new Date(createdAt * 1000).toISOString() : null;

// Flags
const type = String(pick("message[add][0][type]") || "");
const origin = String(pick("message[add][0][origin]") || "");
const is_incoming = (type === "incoming");
const is_whatsapp = origin.includes("amocrmwa");

// Texto cru
const raw_text = String(pick("message[add][0][text]") || "");

return [{
  json: {
    msg_lead_id: msgLead,
    msg_contact_id: msgContact,
    message_ts_iso,
    is_incoming,
    is_whatsapp,
    raw_text
  }
}];

const j = $json;

// IDs do Supabase/rascunho (clique)
const supabase_id   = j.id || null;
const click_lead_id = Number(j.lead_id) || null;

// IDs da MENSAGEM (lead real da conversa)
const msg_lead_id   = Number(j.msg_lead_id) || null;   // veio do webhook
const msg_contact_id= Number(j.msg_contact_id) || null;
const message_ts_iso= j.message_ts_iso || null;

// Janela de pareamento efetiva (só referência/telemetria)
let window_to   = message_ts_iso || new Date().toISOString();
let window_from = null;
try {
  window_from = message_ts_iso
    ? new Date(new Date(message_ts_iso).getTime() - 15*60*1000).toISOString()
    : new Date(Date.now() - 15*60*1000).toISOString();
} catch(e) {
  window_from = new Date(Date.now() - 15*60*1000).toISOString();
}

// Sinalizadores úteis
const is_candidate   = ['locked','pending'].includes(String(j.status || '').toLowerCase());
const has_msg_lead   = !!msg_lead_id;
const has_click_lead = !!click_lead_id;

// Para evitar confusões futuras: "incoming_lead_id" PASSA a ser o da mensagem
const incoming_lead_id = msg_lead_id || null;

// Diferença entre rascunho e mensagem
const is_different_ids = (has_click_lead && has_msg_lead) 
  ? Number(click_lead_id) !== Number(msg_lead_id)
  : false;

return [{
  json: {
    // mantém tudo do item original
    ...j,

    // campos padronizados para os próximos nós
    supabase_id,
    click_lead_id,
    msg_lead_id,
    incoming_lead_id,   // usar ESTE em chamadas à Kommo (with=contacts)
    msg_contact_id,
    message_ts_iso,

