const prev = $input.first().json;

function toUnix(isoString) {
  if (!isoString) return 0;
  const ts = Date.parse(isoString);
  return isNaN(ts) ? 0 : Math.floor(ts / 1000);
}

function clean(str, maxLen) {
  if (!str) return '';
  return String(str).slice(0, maxLen || 255);
}

const body = {
  custom_fields_values: [
    { field_id: prev.config.FIELD_UTM_SOURCE, values: [{ value: clean(prev.click.utm_source) }] },
    { field_id: prev.config.FIELD_UTM_MEDIUM, values: [{ value: clean(prev.click.utm_medium) }] },
    { field_id: prev.config.FIELD_UTM_CAMPAIGN, values: [{ value: clean(prev.click.utm_campaign) }] },
    { field_id: prev.config.FIELD_UTM_TERM, values: [{ value: clean(prev.click.utm_term) }] },
    { field_id: prev.config.FIELD_UTM_CONTENT, values: [{ value: clean(prev.click.utm_content) }] },
    { field_id: prev.config.FIELD_GCLID, values: [{ value: clean(prev.click.gclid) }] },
    { field_id: prev.config.FIELD_FBCLID, values: [{ value: clean(prev.click.fbclid) }] },
    { field_id: prev.config.FIELD_CLICK_TS, values: [{ value: toUnix(prev.click.click_ts) }] },
    { field_id: prev.config.FIELD_MESSAGE_TS, values: [{ value: toUnix(prev.message_ts) }] },
    { field_id: prev.config.FIELD_LAST_PAGE, values: [{ value: clean(prev.click.last_page) }] },
    { field_id: prev.config.FIELD_PAGE_TITLE, values: [{ value: clean(prev.click.page_title) }] }
  ]
};

return {
  ...prev,
  kommo_body: body
};

// ============================================
// PARSE DO WEBHOOK DE CLIQUE
// ============================================

const config = $input.first().json;
const webhookItems = $('Webhook Clique').all();
const webhook = webhookItems.length > 0 ? webhookItems[0].json : {};

// Parse do body
let body;
try {
  body = typeof webhook.body === 'string' ? JSON.parse(webhook.body) : (webhook.body || {});
} catch (e) {
  body = webhook.body || webhook || {};
}

// Extrair user agent curto (para debug/auditoria)
function extractUserAgentShort(ua) {
  if (!ua) return null;

  // Detectar browser e OS
  let browser = 'Unknown';
  let os = 'Unknown';

  if (ua.includes('Chrome')) browser = 'Chrome';
  else if (ua.includes('Firefox')) browser = 'Firefox';
  else if (ua.includes('Safari')) browser = 'Safari';
  else if (ua.includes('Edge')) browser = 'Edge';

  if (ua.includes('Android')) os = 'Android';
  else if (ua.includes('iPhone') || ua.includes('iPad')) os = 'iOS';
  else if (ua.includes('Windows')) os = 'Windows';
  else if (ua.includes('Mac')) os = 'Mac';
  else if (ua.includes('Linux')) os = 'Linux';

  return browser + '/' + os;
}

// Calcular expiração
const expiresAt = new Date(Date.now() + (config.CLICK_EXPIRATION_HOURS * 60 * 60 * 1000));

const userAgent = body.user_agent || webhook.headers?.['user-agent'] || null;
const ip = webhook.headers?.['x-real-ip'] || webhook.headers?.['x-forwarded-for']?.split(',')[0] || null;

return {
  config,

  // UTMs
  utm_source: body.utm_source || null,
  utm_medium: body.utm_medium || null,
  utm_campaign: body.utm_campaign || null,
  utm_term: body.utm_term || null,
  utm_content: body.utm_content || null,
  gclid: body.gclid || null,
  fbclid: body.fbclid || null,

  // Contexto
  click_url: body.click_url || null,
  page_url: body.page_url || null,
  page_title: body.page_title || null,
  first_referrer: body.first_referrer || null,
  first_landing: body.first_landing || null,
  last_page: body.last_page || null,

  // Fingerprint
  ip: ip,
  user_agent: userAgent,
  user_agent_short: extractUserAgentShort(userAgent),
  lang: body.lang || null,

  // Timestamps
  click_ts: new Date().toISOString(),
  expires_at: expiresAt.toISOString(),

  // Multi-tenant
  client_subdomain: config.KOMMO_SUBDOMAIN
};

// O Webhook veio como text/plain; precisamos parsear
const raw = $json.body || '{}';
let data = {};
try { data = JSON.parse(raw); } catch(e){ data = {}; }

// util: extrai phone e text de diferentes formatos
function extractFromClickUrl(uStr){
  try {
    const u = new URL(uStr || 'https://wa.me/');
    const host = u.host || '';
    let number = '';
    let message = '';

    if (host.includes('wa.me')) {
      number = (u.pathname || '').replace(/\//g,''); // /55119...
      message = u.searchParams.get('text') || '';
    } else if (host.includes('api.whatsapp.com')) {
      number = u.searchParams.get('phone') || '';
      message = u.searchParams.get('text') || '';
    } else if (host.includes('wa.link')) {
      // encurtador - aqui deixamos vazio; pode resolver com um HTTP HEAD se quiser expandir
      number = '';
      message = '';
    }
    // normaliza para só dígitos
    number = (number || '').replace(/\D/g, '');
    return { number, message };
  } catch(e){
    return { number:'', message:'' };
  }
}

const { number, message } = extractFromClickUrl(data.click_url);

// Monte o objeto final para os próximos nós
return [{
  json: {
    ...data,
    number,
    message,
    // segurança: defaults
    utm_source:   data.utm_source   || '',
    utm_medium:   data.utm_medium   || '',
    utm_campaign: data.utm_campaign || '',
    utm_term:     data.utm_term     || '',
    utm_content:  data.utm_content  || '',
    first_referrer: data.first_referrer || '',
    first_landing:  data.first_landing  || '',
    last_page:      data.last_page      || '',
  }
}];

// Extrai número e mensagem do link de WhatsApp SEM usar 'URL' (compatível com o sandbox do n8n)
const out = [];

for (const item of $input.all()) {
  const urlStr = String(item.json.click_url || '');

  // tenta pegar telefone via ?phone=... ; se não houver, tenta /wa.me/XXXXXXXX
  let number = '';
  const phoneMatch = urlStr.match(/[?&]phone=([^&#]+)/i);
  if (phoneMatch) {
    number = decodeURIComponent(phoneMatch[1]).replace(/\D/g, '');
  } else {
    // wa.me/5511999999999 ou wa.me/5511999999999?text=...
    const waMatch = urlStr.match(/wa\.me\/([^/?#]+)/i);
    if (waMatch) {
      number = waMatch[1].replace(/\D/g, '');
    }
  }

  // mensagem (?text=...)
  let message = '';
  const textMatch = urlStr.match(/[?&]text=([^&#]+)/i);
  if (textMatch) {
    // + pode vir como espaço – convertemos pra %20 antes do decode
    message = decodeURIComponent(textMatch[1].replace(/\+/g, '%20'));
  }

  out.push({
    json: {
      ...item.json,
      number,
      message,
    }
  });
}

return out;

const number = String($json.number || '').replace(/\D/g,'');
const contacts = $json._embedded?.contacts || [];

function phonesOf(contact){
  const cf = contact.custom_fields_values || [];
  const phoneField = cf.find(f => f.field_code === 'PHONE');
  const values = phoneField?.values || [];
  return values.map(v => String(v.value || '').replace(/\D/g,''));
}

const match = contacts.find(c => phonesOf(c).some(p => p.endsWith(number)));

return [{ ...$json, contact_id: match ? match.id : null }];

/**
 * Code – lead_id + UTMs
 * - Extrai lead_id de vários formatos
 * - Lê o body do Webhook (string JSON), separa e “achata” as UTMs
 */

const item = $json;

// 1) Função utilitária para achar um id em formatos comuns
function pickId(obj) {
  if (!obj || typeof obj !== 'object') return null;
  if (obj.id) return obj.id;
  if (Array.isArray(obj)) return obj[0]?.id ?? null;
  if (obj._embedded?.leads?.[0]?.id) return obj._embedded.leads[0].id;
  if (obj.leads?.[0]?.id) return obj.leads[0].id;
  return null;
}

// 2) Se a API retornou JSON como string em `data`, parseamos
let payload = item;
if (typeof item.data === 'string') {
  try {
    payload = JSON.parse(item.data);
  } catch (e) {
    // segue com item inalterado se não der pra parsear
  }
}

// 3) Extrai o lead_id de forma robusta
let leadId =
  pickId(payload) ??
  pickId(payload._embedded) ??
  pickId(item) ??
  null;

// 4) Pega o body do Webhook (string JSON) para extrair UTMs
let rawBody = item.body; // caso já tenha sido propagado anteriormente
try {
  if (!rawBody && $node && $node['Webhook']?.json?.body) {
    // lê direto do node Webhook: {{ $item("0").$node["Webhook"].json["body"] }}
    rawBody = $node['Webhook'].json.body;
  }
} catch (e) {
  // se o helper $node não estiver disponível, segue sem ele
}

// 5) “Achatamos” os campos de UTM que nos interessam
const utmOut = {};
const keep = [
  'click_url', 'page_url', 'page_title',
  'utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content',
  'first_referrer', 'first_landing', 'last_page',
  'lang', 'user_agent',
];

if (rawBody) {
  try {
    const bodyObj = (typeof rawBody === 'string') ? JSON.parse(rawBody) : rawBody;
    for (const k of keep) utmOut[k] = bodyObj[k] ?? '';
  } catch (e) {
    // body não era JSON válido; ignora UTMs
  }
}

// 6) Retorna o item original + lead_id + UTMs “achatadas”
return [
  {
    json: {
      ...item,
      ...utmOut,
      lead_id: leadId,
    },
  },
];

