// ============================================
// VALIDAR WEBHOOK KOMMO
// ============================================

const config = $input.first().json;
const webhookItems = $('Webhook').all();
const webhook = webhookItems.length > 0 ? webhookItems[0].json : {};
const body = webhook.body || {};

// So processa mensagem incoming
const messageType = body['message[add][0][type]'];
if (messageType !== 'incoming') {
  return { skip: true, reason: 'Nao e incoming', config };
}

const contactId = body['message[add][0][contact_id]'];
const leadId = body['message[add][0][element_id]'] || body['message[add][0][entity_id]'];

if (!contactId || !leadId) {
  return { skip: true, reason: 'Sem contact_id ou lead_id', config };
}

const createdAt = body['message[add][0][created_at]'];
const messageTs = createdAt 
  ? new Date(parseInt(createdAt) * 1000).toISOString() 
  : new Date().toISOString();

return {
  skip: false,
  config,
  contact_id: parseInt(contactId),
  lead_id: parseInt(leadId),
  author_name: body['message[add][0][author][name]'] || '',
  message_ts: messageTs
};

// ============================================
// PROCESSAR RESULTADO DO LOCK
// ============================================

const prev = $('Validar').first().json;
const lockResult = $input.first().json;

// Se não encontrou clique
if (!lockResult || !lockResult.click_id) {
  return {
    ...prev,
    has_match: false,
    reason: 'Nenhum clique na janela de tempo'
  };
}

// Parse do click_data (vem como JSONB)
let clickData;
try {
  clickData = typeof lockResult.click_data === 'string' 
    ? JSON.parse(lockResult.click_data) 
    : lockResult.click_data;
} catch (e) {
  clickData = lockResult.click_data || {};
}

return {
  ...prev,
  has_match: true,
  click_id: lockResult.click_id,
  click: clickData,
  match_score: lockResult.match_score,
  clicks_in_window: lockResult.clicks_in_window
};

// ============================================
// VERIFICAR SE LEAD JA TEM UTM
// ============================================

const prev = $('Processar Lock').first().json;
const lead = $input.first().json;

let hasUtm = false;
if (lead.custom_fields_values) {
  for (const field of lead.custom_fields_values) {
    if (field.field_id === prev.config.FIELD_UTM_SOURCE) {
      if (field.values && field.values[0] && field.values[0].value) {
        hasUtm = true;
        break;
      }
    }
  }
}

// Extrair phone do lead para auditoria
let leadPhone = null;
if (lead.custom_fields_values) {
  for (const field of lead.custom_fields_values) {
    if (field.field_code === 'PHONE' || field.field_type === 'phone') {
      if (field.values && field.values[0] && field.values[0].value) {
        leadPhone = field.values[0].value;
        break;
      }
    }
  }
}

return {
  ...prev,
  lead_has_utm: hasUtm,
  lead_name: lead.name || '',
  lead_phone: leadPhone
};

